impl FromStr for CacheActions {
    type Err = Error;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut cache = CacheActions {
            read: false,
            write: false,
        };

        for c in s.chars() {
            match c {
                'r' => {
                    if cache.read {
                        return Err(Error::DuplicateActions {
                            text: s.to_string(),
                            action: "r (read)",
                            span: None,
                        });
                    }
                    cache.read = true;
                }

                'w' => {
                    if cache.write {
                        return Err(Error::DuplicateActions {
                            text: s.to_string(),
                            action: "w (write)",
                            span: None,
                        });
                    }
                    cache.write = true;
                }
                _ => {
                    return Err(Error::InvalidCacheAction {
                        c,
                        text: String::new(),
                        span: None,
                    });
                }
            }
        }

        Ok(cache)
    }
}

